//! The C ABI of libmpdec (mpdecimal.h), backed by mpdecimal-core.
//!
//! The functions are wrappers generated by systest/gen.py (capi.rs), or
//! written by hand (manual.rs) where the function of mpdecimal-core does not
//! have the C signature. The globals
//! (mpd_mallocfunc, mpd_traphandler, ...) are defined and exported by
//! mpdecimal-core with its feature capi, since C code assigns them.

#![allow(non_camel_case_types, non_snake_case, unused_imports, clippy::all)]

mod capi;
mod manual;

pub use capi::*;
pub use manual::*;
